}
/** 字幕显示模式：双语对照 / 仅目标译文 / 仅原始语言 */
export type SubtitleDisplayMode = "bilingual" | "target_only" | "source_only";
/** 封装输出模式：0.5s 无损软挂载 MKV / NVENC 显卡硬字幕压制 MP4 */
