  }>(),
  {
    steps: () => ['添加文件', '定制选项', '完成交付'],
    uploadButtonText: '选择文件',
    queueTitle: '待处理文件队列',
    actionButtonText: '开始处理',
    dropzoneTitle: '把需要处理的文件拖放到这里',
    dropzoneSubtitle: '支持多选批量排队，本地离线极速处理',
  }
);
const emit = defineEmits<{
