    >
      <div class="max-w-[1580px] w-full mx-auto space-y-8 flex flex-col justify-between pt-1">
        <!-- 上半区：4:8 黄金栅格 -->
        <section class="grid grid-cols-1 lg:grid-cols-12 gap-8 lg:gap-10 items-center">
          <!-- 左翼：大字标、理念与大胶囊按钮 (增加轻微内边距) -->
          <div class="lg:col-span-5 flex flex-col justify-center space-y-5 pl-1 sm:pl-2">
            <div>
              <GradientText
                text="紫电AI"
                :colors="['#A5F3FC', '#D8B4F8', '#A5F3FC', '#D8B4F8']"
                :animation-speed="6"
                class="text-5xl sm:text-6xl lg:text-[68px] font-black tracking-tight"
              />
            </div>
            <p class="text-slate-200 text-sm sm:text-[15px] leading-[1.7] max-w-md font-sans">
              <span class="block text-slate-300">不执着于单点技术的极致拔尖，而是通过全系统协同优化</span>
              <span class="block text-slate-100 mt-1">让 <span class="text-[#ffb74d] font-bold">廉价 AI + 极致框架</span> 创造最大化生产力</span>
            </p>
            <div class="flex items-center gap-3.5 pt-2 flex-wrap">
              <button
                type="button"
                @click="openOfficialWebsite"
                class="h-11 px-6 rounded-2xl bg-white/[0.05] hover:bg-white/[0.1] border border-white/15 hover:border-[#02c3b4]/60 text-white font-black text-sm tracking-wide transition-all duration-200 active:scale-95 flex items-center gap-2.5 cursor-pointer shadow-[0_8px_24px_rgba(0,0,0,0.35)] hover:shadow-[0_10px_30px_rgba(2,195,180,0.2)] hover:scale-[1.02]"
                title="访问官方网站 (https://geantendormi.top/)"
              >
                <Globe :size="17" class="text-[#02c3b4] stroke-[2.2]" />
                <span>官方网站</span>
              </button>
              <button
                type="button"
                @click="triggerFeedbackModal"
                class="h-11 px-5 rounded-2xl bg-white/[0.03] hover:bg-white/[0.07] border border-white/10 hover:border-white/20 text-[#c4d4d6] hover:text-white font-bold text-sm tracking-wide transition-all duration-200 active:scale-95 flex items-center gap-2.5 cursor-pointer shadow-md hover:scale-[1.02]"
                title="意见反馈"
              >
                <MessageSquareHeart :size="17" class="text-rose-400 stroke-[2.2]" />
                <span>意见反馈</span>
              </button>
            </div>
          </div>
          <!-- 右翼：Top 3 旗舰卡片流 -->
          <div class="lg:col-span-7 flex flex-col justify-center w-full min-w-0">
            <ChromaGrid
              :items="flagshipTools"
              @card-click="handleChromaClick"
            />
          </div>
        </section>
        <!-- 下半区：全能工具导航矩阵 -->
        <section id="tool-explorer-section" class="space-y-4 pt-2">
          <div class="flex flex-col md:flex-row md:items-center justify-between gap-3 border-b border-white/[0.06] pb-3">
            <div>
              <h2 class="text-base sm:text-lg font-bold text-white tracking-wide">全能工具导航矩阵</h2>
            </div>
            <div class="flex items-center gap-3 flex-wrap">
              <div class="flex items-center gap-1.5">
                <button
                  v-for="cat in categoryList"
                  :key="cat.id"
                  type="button"
                  @click="activeCategory = cat.id"
                  class="h-7 px-3 rounded-xl text-xs font-bold flex items-center gap-1 transition-all cursor-pointer select-none"
                  :class="activeCategory === cat.id ? 'bg-[#02c3b4]/15 border border-[#02c3b4]/50 text-[#02c3b4] shadow-[0_0_12px_rgba(2,195,180,0.2)]' : 'bg-white/[0.02] border border-white/[0.06] text-[#8b999b] hover:text-white hover:bg-white/[0.04]'"
                >
                  <component :is="cat.icon" :size="12" />
                  <span>{{ cat.label }}</span>
                </button>
              </div>
              <div class="relative w-full sm:w-[240px]">
                <Search :size="13" class="absolute left-3 top-1/2 -translate-y-1/2 text-[#8b999b]" />
                <input
                  v-model="searchQuery"
                  type="text"
                  placeholder="搜索全库算子..."
                  class="w-full h-8 pl-8 pr-3 bg-white/[0.02] border border-white/[0.08] hover:border-white/[0.15] focus:border-[#02c3b4]/50 focus:ring-1 focus:ring-[#02c3b4]/30 rounded-xl text-xs text-[#f5f5f3] outline-none transition-all placeholder-[#5b696b] backdrop-blur-md"
                />
              </div>
            </div>
          </div>
          <!-- 卡片网格 -->
          <div v-if="filteredTools.length > 0" class="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 xl:grid-cols-4 gap-4">
            <article
              v-for="tool in filteredTools"
              :key="tool.id"
              @click="handleToolClick(tool)"
              class="group relative flex flex-col w-full min-w-0 p-2.5 rounded-[22px] overflow-hidden border border-white/10 hover:border-[#02c3b4]/60 bg-[#182022]/85 hover:bg-[#182022]/95 backdrop-blur-2xl transition-all duration-300 shadow-[0_12px_36px_rgba(0,0,0,0.35)] hover:shadow-[0_16px_48px_rgba(2,195,180,0.18)] cursor-pointer select-none"
            >
              <div v-if="tool.image" class="relative z-10 w-full aspect-[16/10] overflow-hidden rounded-[16px] border border-white/[0.08] bg-[#0a0f10]">
                <img
                  :src="tool.image"
                  :alt="tool.name"
                  loading="lazy"
                  class="w-full h-full object-cover group-hover:scale-[1.03] transition-transform duration-500 block select-none pointer-events-none"
                />
              </div>
              <div class="relative z-10 px-2 pt-2.5 pb-1 space-y-1 flex-1 flex flex-col justify-between">
                <div class="flex items-center justify-between">
                  <h3 class="text-sm sm:text-base font-black text-white tracking-tight group-hover:text-[#02c3b4] transition-colors truncate">
                    {{ tool.name }}
                  </h3>
                  <span class="text-[#02c3b4] font-bold text-sm opacity-0 group-hover:opacity-100 group-hover:translate-x-0.5 transition-all duration-200 shrink-0">
                    ➔
                  </span>
                </div>
                <p class="m-0 text-[11px] sm:text-[12px] text-[#8b999b] leading-relaxed group-hover:text-[#d1dddf] transition-colors line-clamp-1">
                  {{ tool.desc }}
                </p>
              </div>
            </article>
          </div>
          <div v-else class="py-10 text-center text-[#8b999b] border border-white/[0.04] rounded-2xl bg-white/[0.01]">
            <p class="text-xs">未找到与 "{{ searchQuery }}" 匹配的工具算子</p>
          </div>
        </section>
      </div>
    </div>
  </div>
</template>use core_security::{
    gatekeeper::{Gatekeeper, QuotaStatus},
    DeviceFingerprint,
};
use format_converter::{service::FormatConvertService, FormatConvertResult, FormatConvertTask};
use pdf_parse::service::{PdfParseResult, PdfParseService};
use shared_contracts::VramTokenGuard;
use std::path::{Path, PathBuf};
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::Arc;
use tauri::{Emitter, State};
use upscale_48k::{Upscale48kTool, UpscaleResult, UpscaleTask};
use video_subtitle::{
    VideoProbeResult, VideoProbeService, VideoSubtitleOptions, VideoSubtitleResult,
    VideoSubtitleTool,
};
pub struct AppState {
    pub vram_guard: Arc<VramTokenGuard>,
    pub output_dir: PathBuf,
    pub cancel_token: Arc<AtomicBool>,
}
#[tauri::command]
async fn get_quota_status() -> Result<QuotaStatus, String> {
    Gatekeeper::get_quota_status().await
}
#[tauri::command]
async fn run_upscale_48k(
    task: UpscaleTask,
    window: tauri::Window,
    state: State<'_, AppState>,
) -> Result<UpscaleResult, String> {
    tracing::info!("🚀 收到前端 4K/8K 视觉超分请求: {:?}", task.input_path);
    // 纯 Token 结算：4K 超分 10 Tokens
    Gatekeeper::check_permission_tokens("upscale-48k", 10).await?;
    let window_clone = window.clone();
    let progress_cb = move |current: usize, total: usize, msg: &str| {
        let _ = window_clone.emit(
            "upscale-progress",
            serde_json::json!({
                "current": current,
                "total": total,
                "message": msg
            }),
        );
    };
    let start_t = std::time::Instant::now();
    let res = Upscale48kTool::execute(task, state.vram_guard.clone(), Some(progress_cb)).await;
    let elapsed = start_t.elapsed().as_millis() as u64;
    Gatekeeper::report_telemetry(
        "upscale-48k",
        elapsed,
        res.is_ok(),
        res.as_ref().err().map(|e| e.as_str()),
    ).await;
    res
}
#[tauri::command]
async fn parse_pdf(
    file_path: String,
    window: tauri::Window,
    state: State<'_, AppState>,
) -> Result<PdfParseResult, String> {
    tracing::info!("🚀 收到前端 PDF 解析请求: {}", file_path);
    // 纯 Token 结算：PDF 解析 2 Tokens
    Gatekeeper::check_permission_tokens("pdf-parse", 2).await?;
    let window_clone = window.clone();
    let progress_cb = move |current: usize, total: usize, msg: &str| {
        let _ = window_clone.emit(
            "pdf-parse-progress",
            serde_json::json!({
                "current": current,
                "total": total,
                "message": msg
            }),
        );
    };
    let pdf_input_path = Path::new(&file_path);
    let target_out_dir = pdf_input_path
        .parent()
        .unwrap_or_else(|| Path::new("."));
    let start_t = std::time::Instant::now();
    let res = PdfParseService::run_parse(
        &file_path,
        target_out_dir,
        Some(&state.vram_guard),
        Some(progress_cb),
    ).await;
    let elapsed = start_t.elapsed().as_millis() as u64;
    Gatekeeper::report_telemetry(
        "pdf-parse",
        elapsed,
        res.is_ok(),
        res.as_ref().err().map(|e| e.as_str()),
    ).await;
    res
}
#[tauri::command]
async fn probe_video(video_path: String) -> Result<VideoProbeResult, String> {
    tracing::info!("🔍 [VideoProbe] 探测视频元信息: {}", video_path);
    let path = std::path::Path::new(&video_path);
    VideoProbeService::probe(path).await
}
#[tauri::command]
async fn run_video_subtitle(
    options: VideoSubtitleOptions,
    state: State<'_, AppState>,
) -> Result<VideoSubtitleResult, String> {
    tracing::info!("🚀 收到前端 视频双语字幕工坊请求: {}", options.video_path);
    let video_p = Path::new(&options.video_path);
    let probe_info = VideoProbeService::probe(video_p).await.ok();
    let duration_sec = probe_info.map(|p| p.duration_sec).unwrap_or(180.0);
    // 纯 Token 结算：按时长负载动态换算 Tokens
    let minutes = (duration_sec / 60.0).ceil() as u32;
    let tokens_needed = (minutes * 3).max(3);
    tracing::info!("⏱️ 视频时长: {:.1} 秒 ➔ 动态消耗 {} Tokens", duration_sec, tokens_needed);
    Gatekeeper::check_permission_tokens("video-subtitle", tokens_needed).await?;
    state.cancel_token.store(false, Ordering::SeqCst);
    let start_t = std::time::Instant::now();
    let res = VideoSubtitleTool::run_pipeline_cancellable(
        options,
        Some(&state.vram_guard),
        state.cancel_token.clone(),
    ).await;
    let elapsed = start_t.elapsed().as_millis() as u64;
    Gatekeeper::report_telemetry(
        "video-subtitle",
        elapsed,
        res.is_ok(),
        res.as_ref().err().map(|e| e.as_str()),
    ).await;
    res
}
#[tauri::command]
fn cancel_current_task(state: State<'_, AppState>) -> Result<bool, String> {
    tracing::warn!("🛑 [IPC 截停专线] 收到前端紧急截停请求");
    state.cancel_token.store(true, Ordering::SeqCst);
    Ok(true)
}
#[tauri::command]
fn get_hardware_fingerprint() -> Result<String, String> {
    let secret = "ai-forge-commercial-secret-2026";
    DeviceFingerprint::new()
        .add_cpu_info()
        .add_mac_address()
        .add_system_info()
        .generate(secret)
        .map_err(|e| e.to_string())
}
#[tauri::command]
async fn run_format_convert(
    task: FormatConvertTask,
    window: tauri::Window,
) -> Result<FormatConvertResult, String> {
    tracing::info!("🚀 收到前端 全能格式转换请求 (0 Tokens): {:?}", task);
    let res = FormatConvertService::convert(&task);
    let _ = window.emit("format-convert-finished", &res);
    Ok(res)
}
#[cfg_attr(mobile, tauri::mobile_entry_point)]
pub fn run() {
    let output_dir = std::env::temp_dir().join("ai_forge_outputs");
    let _ = std::fs::create_dir_all(&output_dir);
    let app_state = AppState {
        vram_guard: Arc::new(VramTokenGuard::default_rtx3060()),
        output_dir,
        cancel_token: Arc::new(AtomicBool::new(false)),
    };
    tauri::Builder::default()
        .plugin(tauri_plugin_opener::init())
        .plugin(tauri_plugin_dialog::init())
        .manage(app_state)
        .invoke_handler(tauri::generate_handler![
            get_quota_status,
            parse_pdf,
            probe_video,
            run_video_subtitle,
            cancel_current_task,
            get_hardware_fingerprint,
            run_format_convert,
            run_upscale_48k
        ])
        .run(tauri::generate_context!())
        .expect("🚨 启动 紫电 AI 桌面端失败");
}[package]
